sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    var payload = event.payload;
    var context_text = JSON.stringify(payload);
    console.log("NeedIt Experience: "+context_text);
    var table = payload.params.table;
    var query = payload.params.query;
    console.log("table: "+table+"\nquery: "+query);
    api.setState("table",table);
    api.setState("query",query);
}
